
#!/usr/bin/perl
#
# The input .tu file should be generated by:
#  tu -d joe -r start -z <tz> -x maez -c <solfile> -H -o <output_file> file.mtm
#
# To run:  perl tu2cal.pl <site> <type> <start_date> <end_date>
#
use strict;
use Time::Local;

# Home-brewed and other modules that are common to multiple programs.
use lib "/home/grad/mfrsr/bin";
use Modules::Check_Site;
use Modules::Check_Dates;
use Modules::Determine_Dates;
use Modules::Site_Info;
use Modules::Time_Calculations;
use Modules::SUNAE;

# Make sure it is user mfrsr running the program
my $user = getlogin();
if ($user !~ /^mfrsr/) {
    print "\n Derp! You are running as user: $user\n";
    print " This program needs to be run by user \'mfrsr\' in order";
    print " to create\n the directories and files with proper ownership.\n";
    die "\n";
}

if (scalar@ARGV != 4) {usage();}
my $tli   = $ARGV[0];
my $type  = $ARGV[1];
my $start = $ARGV[2];
my $end   = $ARGV[3];

my $tli_type = join('_',$tli,$type);
&Check_Site($tli_type);    # Make sure site is valid
&Check_Dates($start,$end); # Make sure dates are valid
my @dates = &Determine_Dates($start,$end);


############################################################################
# Gather site attributes from site_info file.  Necessary to determine site
# type (mfrsr or tower), and for lat/lon if using SUNAE code
#
my %info   = &Site_Info($tli_type); # Ret lat, lon, tz, new_date
my $lat    = $info{LAT};
my $lon    = $info{LON};
my $tz     = $info{TZ};
my $tpdate = $info{NEW};
my $dir    = $info{DIR};

# Establish variable for temporary directory
my $tdir = "/tmp/mfrsrcalproc";
`rm -rf $tdir`;
`mkdir $tdir`;

############################################################################
# Copy .tu files for date range requested into temp directory, and then 
# cd to that directory.  Includes check for existence of files to process.
#
print "\n  Copying files to $tdir\n\n";
my $path = "/data/Inst/MFR/${dir}/${tli}/${type}";  # Common Path
foreach my $date (@dates) {
    my $yyyy = substr($date,0,4);
    `cp ${path}/tu/${yyyy}/${tli}_${type}_${date}*\.tu $tdir`;
}
chdir "$tdir";  # Changing to temporary directory $tdir
my @files = `ls \*\.tu`;
if (scalar @files == 0) {die "\nNo .tu files to process";}

############################################################################
# Begin loop to process each file.
#
foreach my $file (@files) {

# Pulling info from tu filename
    chomp $file;
    print STDOUT "Processing tu file: $file\n";
    my ($date,$hexb,$hexh,$sn) = (split /_/,$file)[2,3,4,5];
    $sn = sprintf "%4.4d",$sn;

############################################################################
# Retrieve calibration information from file located in
# /home/grad/mfrsr/Calinfo/CAL
#
# Returns refs to hashes for Cals and Offsets, and
# a hash ref of sensor info (serial number, head hexID, log hexID)
#
# $rCAL & $cOS keys are: ch1, ch2...ch7, where ch1=BB, ch4=615|1625
#
    my ($rCAL,$rOS,$rINFO) = calibration($tli,$type,$date,$file); 

#    print "working\n";
#    foreach my $k1 (keys %$rCAL) {
#	print "> $k1 @{$$rCAL{$k1}}\n";
#    }
#    print "working\n";
#    sleep 2;
############################################################################
# Gather logger gain/offset information for apropriate logger from 
# /home/grad/mfrsr/Calinfo/LoggerGains
#
# keys are: ch1, ch2 ... ch7, where ch1=BB, ch4=615|1625
#
    my $rGAIN = loggergains($hexb); # Hash ref to Logger Gains and Offsets

############################################################################
# Gather diffuse correction information.  Returns a hash reference ($rDC) 
# of the corrections.
#
# keys are: ch1, ch2 ... ch7, where ch1=BB, ch4=615|1625
#
    my $rDC = diffusecorr($tli,$type,$date,$lat,$file);


    my $header_flag = "N"; # To read header line
    my $tpf = "N";         # Thermopile instrument (Y/N)
    my $z;                 # Array (@el) index adjustment for TP/si, etc.
    my $addflds = "N";     # Additional fields (UVB_Sig, UVB_Temp, and PAR)
    my $ctype;             # Var that holds the calibration type, e.g., Yankee
    my $rLAMP;             # Hash Ref to Standard Lamp data
    open (IF, "<$file");
    open (OF, ">${tli}_${type}_${date}_${sn}.cal");
    while (<IF>) {
	chomp;
	my ($srt,$dlv); # Head_Temp, Log_V
#
# Several things are done with the header line of each file
#	
	if ($header_flag eq "N") {
	    $header_flag = "Y"; 
	    if ($hexh =~ /\d\d\d\d/) {$hexh = int($hexh);} # Set to 0 if 0000
	    my ($idb,$idh,$init) = (split/\s+/, $_)[1,2,12];
	    $idh = sprintf "%04s",$idh;  # Pad with zeros
	    $idb = sprintf "%04s",$idb;  # Pad with zeros
	    if ($hexh ne $idh) {
		print "\nHead ID from filename:           \"$hexh\"\n";
                print "does not match string from file: \"$idh\"\n\n";
	    }
	    if ($hexb ne $idb) {
		print "\nBoard ID from filename:          \"$hexb\"\n";
                print "does not match string from file: \"$idb\"\n\n";
	    }

###############################################################################
# Determine indexing adjustment for data based on the initialization string
# and the flags set in the poll.pl config files.  Necessary to correctly
# apply cals as @el size varies depending on instrument config.  We also set
# the flag in this section to indicate a thermopile instrument.  This
# cannot be done solely by interrogating the raw/tu files, so we have to
# also rely on the date a thermopile unit was installed.
#
#  flag = 20, MFRSR
#  11FF = Array size 36, Alltime channels w/head_temp, log_volt, and therm_volt
#   1FF = Array size 35, Alltime channels w/head_temp and log_volt
#   101 = Array size 28, Alltime channels off, head_temp and log_volt
#
#  flag = 00, MFR10
#  11FF = Array size 15, Alltime channels w/head_temp, log_volt, and therm_volt
#  73FF = Array size xx, Alltime channels as above with UVB_Sig, UVB_T, and PAR
#  33FF = Array size xx, Alltime channels, no TPV, with UVB_Sig, UVB_T, and PAR
#   1FF = Array size xx, Alltime channels w/head_temp and log_volt
#
	    if ($date >= $tpdate) {$tpf = "Y";} # Thermopile (TP) inst flag
	    if ($type eq "mfrsr") {
		if ($init eq "11FF")   {$z =  0;}
		elsif ($init eq "1FF") {$z = -1;}
		elsif ($init eq "101") {$z = -8;}
		else {
		    print "\n                 *** ERROR! ***\n";
		    print " Unexpected init string ($init) in $file\n";
		    print " Expected init strings are: 11FF, 1FF, and 101\n";
		    print " Probably a unique string, so";
		    print " raw files can be moved to a quarantine dir\n\n";
		    die;
		}
	    }
	    if ($type eq "mfr10") {
		if ($init eq "11FF")    {$z = 0;}
		elsif ($init eq "1FF")  {$z = 0;}
		elsif ($init eq "33FF") {$z = 0; $addflds = "Y"}
		elsif ($init eq "73FF") {$z = 1; $addflds = "Y"}
		else {
		    print "\n                 *** ERROR! ***\n";
		    print " Unexpected init string ($init) in $file\n";
		    print " Expected init strings: 11FF, 1FF, 33FF, and 73FF\n";
		    print " Probably a unique string, so";
		    print " raw files can be moved to a quarantine dir\n\n";
		    die;
		}
	    }
	    $ctype = $$rINFO{format};  # Retrieving Format_CAL
	    if ($ctype eq "StdLamp") { 
		my $lamp = $$rINFO{lamp};       # Get lamp SN
	        $rLAMP = get_lamp_data($lamp);  # Load lamp data
	    }
	    next; # Once header file is read go back and read 1st line of data
	}         # End of reading header section

	my @el    = split/\s+/, $_;  # @el is the array that holds tu data
	my $size = scalar @el;

###########################################
# 19700101 - 19000101 = 2208988800 seconds
#
# Using the above constant to simplify time/date calculations.  That
# number is the elapsed seconds between 1 Jan 1900 and 1 Jan 1970.
#
# tu (raw2tu.pl) is configured to output time in LST to be compatible
# with the Langley analysis (la) program.  So below we are accounting 
# for that and first converting to GMT by using $tz from site attributes.
#
	$el[0] = $el[0] - $tz/24;  # Converting to GMT
	my $secs = int($el[0] * 86400 + 0.5)-86400-2208988800;
	my ($ss,$mn,$hh,$dd,$mm,$yyyy) = (gmtime($secs))[0,1,2,3,4,5];
	$yyyy += 1900;
	$mm++;
	my $YYYYMMDD       = sprintf "%4.4d%2.2d%2.2d",$yyyy,$mm,$dd;
	my $YYYYMMDDhhmmss = sprintf "%8d%2.2d%2.2d%2.2d",$YYYYMMDD,$hh,$mn,$ss;
        my @time_formats   = &Time_Calculations ($YYYYMMDDhhmmss);
        my $fYYYYMMDD = $time_formats[1];
        my $fdoy      = $time_formats[2];
        my $fyear     = $time_formats[3];

##########################################
# Uncomment five lines to use included SUNAE code rather than 
# values from tu.  (Note that tu also uses SUNAE).  Will then
# need to comment the corresponding two lines that follow.
#
#	my $cdiy  = $time_formats[4];
#	my $fhr   = $time_formats[5];
#	my @sunae = &SUNAE($yyyy,$cdiy,$fhr,$lat,$lon);
#	my $az    = $sunae[0];
#	my $sza   = 90-$sunae[1];
	my $az    = $el[$size-3];   # Comment if using preceding SUNAE calcs
	my $sza   = $el[$size-1];   # Comment if using preceding SUNAE calcs
	my $csza  = cos(deg2rad($sza));
	my $am    = $el[$size-4];   # Air Mass from tu


##########################################
# Head temperature calculation.  Code taken from Yankee MFRSR cal file.
#
	if ($el[1] > 2000) {
	    $srt = 6810 * (5000 / $el[1] -1);
	    $srt = 1.030852e-3+2.389179e-4 * 
		   log($srt) + 1.574641e-7 * log($srt)**3;
	    $srt = 1.0 / $srt - 273.12;
	} else {
	    $srt = -99.99;
	}

##########################################
# Data logger supply voltage.  Code taken from Yankee MFRSR cal file.
#
	$dlv = $el[9] * 6.0 / 1000.0;


#########################################################################
# First we apply the offsets to the data.  We first assume nighttime
# data have been collected, analyzed, and included in the appropropriate
# calibration file for the site/sensor being processed.  If this hasn't
# happened, then offsets are determined by the algorithm used in
# standard Yankee .CAL files.  This code is not written yet.  Placeholder
# exists.
#
# Apply the offsets to elements of @el.  Note that direct MFRSR values do
# not have nighttime offset data applied as the offset divides out during
# the direct calculation. $z is the array adjustment based on init string.
#
# BASELINE (11FF) INDEXES:  MFR10 ALLTIME channels (2,3,4,5,6,7,8)
#                           MFRSR TOTAL channels   (11,12,13,14,15,16,17)
#                           MFRSR DIFFUSE channels (18,19,20,21,22,23,24)
#                           MFRSR DIRECT channels  (25,26,27,28,29,30,31)
#
	if ($type eq "mfrsr") {
	    foreach my $x (1..7) {
		my $key = "ch".$x; # keys are ch1, ch2...ch7
		if ($el[10+$x+$z] > -999) { # GLOBAL starts w/11: 10+$x
		    $el[10+$x+$z] -= polyeq($srt,$$rOS{$key}); 
		}
		if ($el[17+$x+$z] > -999) { # DIFFUSE starts w/18: 17+$x
		    $el[17+$x+$z] -= polyeq($srt,$$rOS{$key});
		}
	    }
	}

	if ($type eq "mfr10") {
	    foreach my $x (1..7) {
		my $key = "ch".$x; # keys are ch1, ch2...ch7
		if ($el[1+$x] > -999) { # ALLTIME starts with 2, i.e. 1+$x
		    $el[1+$x] -= polyeq($srt,$$rOS{$key});
		}
	    }
	}

# The above offset code assumes nighttime offset data exists.  That is 
# the ideal way to get offset data.  If it doesn't, then use the 
# algorithm given in a standard Yankee .CAL file.
#
# The standard Yankee offset code will go here.
#

#########################################################################
# Below are the sections where calibrations are applied to the data.
# There are several similar sections necessary to account for different
# instrument initializations, e.g. 11FF or 1FF: Different calibration
# methods, e.g. Yankee, Standard Lamp, Langley:  As well as and related
# to if an instrument is a new style with a thermopile broadband channel,
# or an older unit with a silicon broadband detector.
#
# Calibration data are contained in the hash reference $rCAL
#
# Each section checks for: Sensor type $type  (mfrsr/mfr10)
#                          Format_CAL  $ctype (Yankee, StdLamp, Langley)
#                          Thermopile  $tpf   (Y/N)
#
#########################################################################
#  Sensor:     mfrsr
#  Format_CAL: Yankee
#  Thermopile: Y
#
	if (($type eq "mfrsr") && ($ctype eq "Yankee") && ($tpf eq "Y")) {
	    foreach my $x (1..7) {
		my $key  = "ch".$x; # keys are ch1, ch2...ch7

# When key=ch1 produce calibrated BROADBAND values for the MFRSR
# thermopile channel (DIFFUSE, DIRECT, GLOBAL).  This is done in
# SUBROUTINE tp_mfrsr. The method used is from a standard Yankee cal file.
#
		if ($key eq "ch1") {
		    if (($el[10+$x+$z] > -999) &&
			($el[17+$x+$z] > -999) &&
			($el[24+$x+$z] > -999)) { 
			my $bbcal = (@{$$rCAL{$key}})[0]; # BB CAL value
			my $bbscf = (@{$$rCAL{$key}})[1]; # BB Scale Factor
			my $tpg   = ${$$rGAIN{tp}}[0];    # TP gain
			my $tpbos = ${$$rGAIN{tp}}[1];    # TP board offset
			my $bbg   = ${$$rGAIN{$key}}[0];  # Broadband gain
			my $bbdc  = $$rDC{$key};          # Broadband DifCor
			my @tpvals = &tp_mfrsr($el[10],       # TP_HTR CNTS
					       $el[10+$x+$z], # TP_GLOBAL CNTS
					       $el[17+$x+$z], # TP_DIFFUSE CNTS
					       $el[24+$x+$z], # TP_DIRECT CNTS
					       $bbcal,        # BB_Calibration
					       $bbscf,        # BB_Scale_Factor
					       $tpg,          # TP_Gain
					       $tpbos,        # TP_Board_Offset
					       $bbg,          # BB_Gain
					       $bbdc,         # BB_DifCor
					       $csza);        # Cosine_SZA
			$el[17+$x+$z] = $tpvals[0];
			$el[24+$x+$z] = $tpvals[1];
			$el[10+$x+$z] = $tpvals[2];
			next; # Next foreach iteration after tp_mfrsr calc.
		    } else {
			$el[10+$x+$z] = -9999;
			$el[17+$x+$z] = -9999;
			$el[24+$x+$z] = -9999;
		    }
		}
		    
# When key=ch[2,3..7] produce calibrated NARROWBAND MFRSR
# values (GLOBAL, DIFFUSE, DIRECT)
#
# DIFFUSE = (<Offset_Corr_Counts> / (<Cal>*<Gain>)) / <difcor>
# DIRECT  = <Cosine_Corr_Counts> / (<Cal>*<Gain>)
# GLOBAL  = <DIFFUSE> + <DIRECT>*COS_SZA
#
		my $cal  = (@{$$rCAL{$key}})[1]; # 2nd element if not BB
		my $gain = ${$$rGAIN{$key}}[0];  # De-ref array, 1st element
		my $dc   = $$rDC{$key};          # DiffCorr value
		if ($el[17+$x+$z] > -999) {   # Narrow DIFFUSE (19 - 24)
		    $el[17+$x+$z] = ($el[17+$x+$z]/($cal*$gain))/$dc;
		}
		if ($el[24+$x+$z] > -999) {   # Narrow DIRECT (26 - 31)
		    $el[24+$x+$z] = $el[24+$x+$z]/($cal*$gain);
		}
		                              # Narrow GLOBAL (12 - 17)
		if (($el[17+$x+$z] > -999) && ($el[24+$x+$z] > -999)) { 
		    $el[10+$x+$z] = $el[17+$x+$z] + $el[24+$x+$z]*$csza;
		}
	    }
	}



#########################################################################
#   Sensor:     mfrsr
#   Format_CAL: StdLamp
#   Thermopile: N
#
	if (($type eq "mfrsr") && ($ctype eq "StdLamp") && ($tpf eq "N")) {
	    foreach my $x (1..7) {
		my $key  = "ch".$x; # keys are ch1, ch2...ch7

# When key=ch1 produce calibrated BROADBAND values for the 
# MFRSR silicon channel (GLOBAL, DIFFUSE, DIRECT)
#
		if ($key eq "ch1") {
		    if (($el[10+$x+$z] > -999) &&
			($el[17+$x+$z] > -999) &&
			($el[24+$x+$z] > -999)) { 
			my $bbcal = (@{$$rCAL{$key}})[0]; # BB CAL value
			my $bbscf = (@{$$rCAL{$key}})[1]; # BB Scale Factor
			my $bbg   = ${$$rGAIN{$key}}[0];  # Broadband gain
			my $bbdc  = $$rDC{$key};          # Broadband DifCor
			my @tpvals = &si_mfrsr($el[10+$x+$z], # TP_GLOBAL CNTS
					       $el[17+$x+$z], # TP_DIFFUSE CNTS
					       $el[24+$x+$z], # TP_DIRECT CNTS
					       $bbcal,        # BB_Calibration
					       $bbscf,        # BB_Scale_Factor
					       $bbg,          # BB_Gain
					       $bbdc);        # BB_DifCor
			$el[17+$x+$z] = $tpvals[0];
			$el[24+$x+$z] = $tpvals[1];
			$el[10+$x+$z] = $tpvals[2];
			next; # Next foreach iteration after tp_mfrsr calcs.
		    } else {
			$el[10+$x+$z] = -9999;
			$el[17+$x+$z] = -9999;
			$el[24+$x+$z] = -9999;
		    }
		}
		
# When key=ch[2,3..7] produce calibrated NARROWBAND MFRSR
# values (GLOBAL, DIFFUSE, DIRECT)
#
# DIFFUSE: (<Offset_CorCnts> / (<Lamp_On>/1000/<Lamp_Output>*<Gain>)) / <difcor>
# DIRECT:   <Cosine_CorCnts> / (<Lamp_On>/1000/<Lamp_Output>*<Gain>)
# GLOBAL:   <DIFFUSE> + <DIRECT>*COS_SZA
#
		my $cwl  = (@{$$rCAL{$key}})[0]; # Center Wavelength
		my $on   = (@{$$rCAL{$key}})[1]; # Lamp_On value
		my $off  = (@{$$rCAL{$key}})[2]; # Lamp_Off value
		my $val  = $on - $off;           # Lamp_On - Lamp_Off
		my $gain = ${$$rGAIN{$key}}[0];  # De-ref array, 1st element
		my $dc   = $$rDC{$key};          # DiffCorr value
		my $lo   = $$rLAMP{$cwl};        # Lamp Output for $cwl
		
		if ($el[17+$x+$z] > -999) {   # Narrow DIFFUSE (19 - 24)
		    $el[17+$x+$z] = ($el[17+$x+$z]/($val/1000/$lo*$gain))/$dc;
		}
		if ($el[24+$x+$z] > -999) {   # Narrow DIRECT (26 - 31)
		    $el[24+$x+$z] = $el[24+$x+$z]/($val/1000/$lo*$gain);
		}
		                              # Narrow GLOBAL (12 - 17)
		if (($el[17+$x+$z] > -999) && ($el[24+$x+$z] > -999)) { 
		    $el[10+$x+$z] = $el[17+$x+$z] + $el[24+$x+$z]*$csza;
		}
	    }
	}



#########################################################################
#  Sensor:     mfr10
#  Format_CAL: Yankee
#  Thermopile: Y
#
	if (($type eq "mfr10") && ($ctype eq "Yankee") && ($tpf eq "Y")) {
	    foreach my $x (1..7) {
		my $key = "ch".$x;  # keys are ch1, ch2...ch7

# When key=ch1 produce calibrated BROADBAND value for the 
# MFR10 thermopile channel.  This is done in SUBROUTINE tp_mfr10.
# The method used is from a standard Yankee cal file.
#
		if ($key eq "ch1") {
		    if ($el[1+$x] > -999) {
			my $bbcal = (@{$$rCAL{$key}})[0]; # BB CAL value
			my $bbscf = (@{$$rCAL{$key}})[1]; # BB Scale Factor
			my $tpg   = ${$$rGAIN{tp}}[0];    # TP gain
			my $tpbos = ${$$rGAIN{tp}}[1];    # TP board offset
			my $bbg   = ${$$rGAIN{$key}}[0];  # Broadband gain
			my $bbdc  = $$rDC{$key};          # Broadband DifCor
			$el[1+$x] = &tp_mfr10($el[10+$z], # TP_HTR CNTS
					      $el[1+$x],  # BB_GLOBAL CNTS
					      $bbcal,     # BB_Calibration
					      $bbscf,     # BB_Scale_Factor
					      $tpg,       # TP_Gain
					      $tpbos,     # TP_Board_Offset
					      $bbg,       # BB_Gain
					      $bbdc);     # BB_DifCor
			next; # Next foreach iteration after tp_mfrsr calcs
		    } else {
			$el[1+$x] = -9999;
		    }
		}
# When key=ch[2,3..7] produce calibrated NARROWBAND MFR10 values
#
# DIFFUSE = ((<Offset_Corr_Counts> / (<Cal>*<Gain>)) / <difcor>) * <scale_fact>
#
# Lamp_On_Val : mV
# Lamp_Output : W m-2
# Gains       : counts/V
#
		my $cal  = (@{$$rCAL{$key}})[1]; # De-ref array, 2nd element
		my $scf  = (@{$$rCAL{$key}})[3]; # Narrowband Scale Factor
		my $gain = ${$$rGAIN{$key}}[0];  # De-ref array, 1st element
		my $dc   = $$rDC{$key};          # DiffCorr value

		if ($addflds eq "N") {
		    if ($el[1+$x] > -999) {      # Narrow ALLTIME (2 - 8)
			$el[1+$x] = (($el[1+$x]/($cal*$gain))/$dc)*$scf;
		    }
		} else {  # Process additional fields ($addflds = Y)
		    if ($el[1+$x] > -999) {
			$el[1+$x] = (($el[1+$x]/($cal*$gain))/$dc)*$scf;
		    }
#		    $el[10] = &uvb_temp($el[10]);
#		    $el[12]= $el[12]*$calUVB[0]/$calUVB[1];
#		    $el[13]= ($el[13]/237.5)*($calPAR[2]/$calPAR[0])/4.6;
		}
	    }
	}




#########################################################################
#   Sensor:     mfr10
#   Format_CAL: StdLamp
#   Thermopile: N
#
	if (($type eq "mfr10") && ($ctype eq "StdLamp") && ($tpf eq "N")) {
	    foreach my $x (1..7) {
		my $key  = "ch".$x; # keys are ch1, ch2...ch7

# When key=ch1 produce calibrated BROADBAND values for the 
# MFRSR silicon channel (GLOBAL, DIFFUSE, DIRECT)
#
		if ($key eq "ch1") {
		    if ($el[1+$x] > -999) {
			my $bbcal = (@{$$rCAL{$key}})[0]; # BB CAL value
			my $bbscf = (@{$$rCAL{$key}})[1]; # BB Scale Factor
			my $bbg   = ${$$rGAIN{$key}}[0];  # Broadband gain
			my $bbdc  = $$rDC{$key};          # Broadband DifCor
			$el[1+$x] = &si_mfr10($el[1+$x],  # BB CNTS
					      $bbcal,     # BB_Calibration
					      $bbscf,     # BB_Scale_Factor
					      $bbg,       # BB_Gain
					      $bbdc);     # BB_DifCor
			next; # Next foreach iteration after tp_mfrsr calcs
		    } else {
			$el[1+$x] = -9999;
		    }
		}
#zzz
# When key=ch[2,3..7] produce calibrated NARROWBAND MFR10 value
#
# DIFFUSE: (<Offset_CorCnts> / (<Lamp_On>/1000/<Lamp_Output>*<Gain>)) / <difcor>
#
# Lamp_On_Val : mV
# Lamp_Output : W m-2
# Gains       : counts/V
#
		my $cwl  = (@{$$rCAL{$key}})[0]; # Center Wavelength
		my $scf  = (@{$$rCAL{$key}})[3]; # Narrowband Scale Factor
		my $on   = (@{$$rCAL{$key}})[1]; # Lamp_On value
		my $off  = (@{$$rCAL{$key}})[2]; # Lamp_Off value
		my $val  = $on - $off;           # Lamp_On - Lamp_Off
		my $gain = ${$$rGAIN{$key}}[0];  # De-ref array, 1st element
		my $dc   = $$rDC{$key};          # DiffCorr value
		my $lo   = $$rLAMP{$cwl};        # Lamp Output for $cwl
		
		if ($el[1+$x] > -999) {   # Narrow ALLTIME (2 - 8)
		    $el[1+$x] = (($el[1+$x]/($val/1000/$lo*$gain))/$dc)*$scf;
		}
	    }
	}

##########################################
# Begin print statement for outputting data files
#
	if ($type eq "mfr10") {
	    printf OF "%14d %11.5f %14.5f %9.5f %13.8f %7.4f %6.2f %5.2f %7.5f %5.2f %5.2f     %6.1f %7.4f %7.4f %7.4f %7.4f %7.4f %7.4f\n",$YYYYMMDDhhmmss,$el[0],$fYYYYMMDD,$fdoy,$fyear,$am,$az,$sza,$csza,$srt,$dlv,@el[2..8];
	}
	if ($type eq "mfrsr") {
	    printf OF "%14d %11.5f %14.5f %9.5f %13.8f %7.4f %6.2f %5.2f %7.5f %5.2f %5.2f     %7.4f %7.4f %7.4f %7.4f %7.4f %7.4f %7.4f     %7.4f %7.4f %7.4f %7.4f %7.4f %7.4f %7.4f     %7.4f %7.4f %7.4f %7.4f %7.4f %7.4f %7.4f\n",$YYYYMMDDhhmmss,$el[0],$fYYYYMMDD,$fdoy,$fyear,$am,$az,$sza,$csza,$srt,$dlv,@el[11+$z..31+$z];
	}
    }
    close (OF);
    close (IF);
}

