sub uvb_temp () {
    my $uvbtc = shift(@_); # UVB Temp Counts
    my $uvbt;

    
    if ($uvbtc > 400) {
	$uvbt = 6810 * (2500 / $uvbtc - 1);
	if ($uvbt < 1) {$uvbt = 10;} # For bad UVB_Temp values
	$uvbt = 1.030852e-3 + (2.389179e-4 * log($uvbt)) +
	    (1.574641e-7 * log($uvbt)**3);
	$uvbt = 1.0 / $uvbt - 273.12;
    } else {
	$uvbt = -99.99;
    }
    return ($uvbt);
}
1;




