sub tp_mfr10 () {
############################
# This subroutine makes MFRSR thermopile data corrections and
# returns corrected values
#
# NOTE: Generally we can think of "Thermopile" and "Broadband" as
# interchangeable.  The only real distinction comes when considering
# 
#
    my $htrcnt = shift(@_); # Thermopile heater voltage counts
    my $totcnt = shift(@_); # Broadband GLOBAL counts
    my $cal    = shift(@_); # Broadband Calibration value
    my $scf    = shift(@_); # Broadband Scale Factor
    my $tpg    = shift(@_); # Thermopile Board gain
    my $os     = shift(@_); # Thermopile Board offset
    my $bbg    = shift(@_); # Broadband Board gain
    my $dc     = shift(@_); # Broadband Diffuse Correction

#    print "\$htrcnt is: $htrcnt\n";
#    sleep 100;

    my $VHTR = ($htrcnt - $os)/$tpg;
    my $c0 =  1.0023;
    my $c1 =  0.0008769;
    my $c2 = -0.00030897;
    my $c3 =  0.000005350;
    my $CORR = $c0 + ${c1}*$VHTR + ${c2}*${VHTR}**2 + ${c3}*${VHTR}**3;
    my $calcor = $cal / $CORR;  # $calcor = C0A in Yankee .CAL file

    my $d0  = 10.45;
    my $d1  =  0.4177;
    my $d2  =  0.1703;
    my $d3  = -0.02640;
    my $C0B = ($d0 + ${d1}*$VHTR + ${d2}*${VHTR}**2 + ${d3}*${VHTR}**3)/1000;

    my $DIFF = ($totcnt - ($calcor*$bbg) - $os) / ($dc*$cal*$bbg);
    return ($DIFF);
}
1;




sub tp_mfrsr () {
############################
# This subroutine makes MFRSR thermopile data corrections and
# returns corrected values
#
    my $htrcnt = shift(@_); # Thermopile Heater Voltage Counts
    my $totcnt = shift(@_); # Broadband GLOBAL Counts
    my $difcnt = shift(@_); # Broadband DIFFUSE Counts
    my $dircnt = shift(@_); # Broadband DIRECT Counts
    my $cal    = shift(@_); # Broadband Calibration Value
    my $scf    = shift(@_); # Broadband Scale Factor
    my $tpg    = shift(@_); # Thermopile Board Gain
    my $os     = shift(@_); # Thermopile Board Offset
    my $bbg    = shift(@_); # Broadband Board Gain
    my $dc     = shift(@_); # Broadband Diffuse Correction
    my $csza   = shift(@_); # Cosine Solar Zenith Angle

    my $VHTR = ($htrcnt - $os)/$tpg;
    my $c0 =  1.0023;
    my $c1 =  0.0008769;
    my $c2 = -0.00030897;
    my $c3 =  0.000005350;
    my $CORR = $c0 + ${c1}*$VHTR + ${c2}*${VHTR}**2 + ${c3}*${VHTR}**3;
    my $calcor = $cal / $CORR;  # $calcor = C0A in Yankee .CAL file

    my $d0  = 10.45;
    my $d1  =  0.4177;
    my $d2  =  0.1703;
    my $d3  = -0.02640;
    my $C0B = ($d0 + ${d1}*$VHTR + ${d2}*${VHTR}**2 + ${d3}*${VHTR}**3)/1000;

    my $DIFF = ($difcnt - ($C0B*$bbg) - $os) / ($dc*$calcor*$bbg);
    my $DIRN = $dircnt / ($calcor*$bbg);
    my $TOT = ($totcnt - $difcnt)/($calcor*$bbg) + $DIFF;
    my $CDIF = $DIFF * (1.01 + 0.01 * $DIRN/$DIFF);
    my $DIRH = 1.018 * ($TOT - $CDIF);
    my $CDIR = $DIRH/$csza;
    my $CTOT = $CDIF + $DIRH;

    return ($CDIF,$CDIR,$CTOT);
}
1;




sub getdatekey () {
############################
# This subroutine looks at the data date and determines
# the appropriate offset/calibration to use.
#
# There is very likely a more clever way to accomplish
# the task of this subroutine!
#
    my $cmp   = shift(@_);
    my @dates = @_;

    my $num = scalar(@dates);
    if ($num == 0) {die "\n   There are no cal dates to compare!!";}
    my $keydate = -999;
    if ($num > 1) {
	foreach my $i (0..$num-1) {
	    if ( ($cmp >= $dates[$i]) && ($cmp < $dates[$i+1]) ) {
		$keydate = $dates[$i];
	    }
	} 
	if ($keydate == -999) {
	    if ($cmp >= $dates[$num-1]) {
		$keydate = $dates[$num-1];
	    }
	}
    } else {
	if ($cmp >= $dates[0]) {
	    $keydate = $dates[0];
	}
    }
#    print ">$cmp : $keydate => @dates\n";    
    if ($keydate == -999) {
	print "\n Data Date: $cmp\n";
	print " Cal Dates: @dates\n";
	print " No valid calibrations for this input \"Data\" date.\n";
	print " Data date needs to be >= one of the calibration dates.\n";
	die "\n Killed program";
    }
    return ($keydate);
}
1;





sub calibration () {
##########################################################################
# Subroutine calibration gathers the relevant calibration information for 
# the site_instrument from the appropriate calibration file.  This code 
# loads three hashes.  One for the calibration data, and one for the 
# nighttime offset data.  The third hash contains sensor info from the cal
# file (serial number, head hexID, and logger hexID). 
#
# References to each hash are returned to the main program.
#
# Calibration files are located in /home/grad/mfrsr/Calinfo/CAL
# File format is: <site>_<sensor>_<date>.cal
#
#  where site is:    bnd, dra, fpe, etc.
#  sensor is either: mfrsr or mfr10
#  and date is:      YYYYMMDD
#
    my $tli = shift(@_);
    my $type = shift(@_);
    my $date = shift(@_);
    my $tuf  = shift(@_); # Working tu file

# Pull IDs from tu file for later sanity checks against cal file    
    my ($hexb,$hexh,$sn) = (split /_/,$tuf)[3,4,5];
    $sn = (split /\./,$sn)[0];

    my $path = "/home/grad/mfrsr/Calinfo/CAL";
    my @listing = `ls -1 ${path}/${tli}_${type}*.cal`;
    chomp @listing;
    @listing = reverse@listing;

    my $calfile;
  OUTER:
    foreach my $file (@listing) {
        my $caldate = (split '_',$file)[2];  # Extracting date.cal from file
	$caldate = (split '\.',$caldate)[0]; # Returning only date
        if ($caldate <= $date) {
            $calfile = $file;
            last OUTER;
        }
    }

    if (! -f $calfile) { # If file does not exist
        print "\n              *** ERROR! ***\n";
        print " There is no .cal file for ${tli}_${type}_${date}\n";
        print " Check ${path}/ for a .cal file \n\n";
        die;
    }
    
    my $cfn = (split(/\//,$calfile))[-1]; # Return only cal filename
    print "Cal file used is:   $cfn\n";

    open(IF, $calfile) or die "Can't open $calfile: $!\n";

    my $cal_flag    = "N";
    my $off_flag    = "N";
    my $format_flag = "N";
    my (%cal,%offset,%sensinfo);    # Hashes: Calibration and Offset

    while (<IF>) {
	chomp;
	next if /^\s*$/;     # Skip blank lines                             
	next if /^\s*\#/;    # Skip comment lines                           
	s/\#.*$//;           # Strip tag comment                            

	if (/^SN/) {     # Read serial number, add to HASH %sensinfo
	    $sensinfo{sn} = (split/\s+/, $_)[1]; 
	    if ($sensinfo{sn} != $sn) {
		print "\n     ***ERR: May need to create a CAL file!***\n";
		print " The SNs in the cal file and the";
		print " tu file do not match\n";
		print "  -> From ${calfile}:\n";
		print "      SN is: $sensinfo{sn}\n";
		print "  -> Expected based on tu file: $tuf\n";
		print "      SN is: $sn\n\n";
		die;
	    }
	    next;
	}
	if (/^Head/) {   # Read Sensor HexID, add to HASH %sensinfo
	    $sensinfo{hexh} = (split/\s+/, $_)[1]; 
	    $sensinfo{hexh} = substr($sensinfo{hexh},1,4); # Remove $
	    if ($sensinfo{hexh} ne $hexh) {
		print "\n     ***ERR: May need to create a CAL file!***\n";
		print " The head hexIDs in the cal file and the";
		print " tu file do not match\n";
		print "  -> From ${calfile}:\n";
		print "      Head hexID is: $sensinfo{hexh}\n";
		print "  -> Expected based on tu file: $tuf\n";
		print "      Head hexID is: $hexh\n\n";
		die;
	    }
	    next;
	}
	if (/^Logger/) { # Read Logger HexID, add to HASH %sensinfo
	    $sensinfo{hexb} = (split/\s+/, $_)[1]; 
	    $sensinfo{hexb} = substr($sensinfo{hexb},1,4); # Remove $
	    if ($sensinfo{hexb} ne $hexb) {
		print "\n     ***ERR: May need to create a CAL file!***\n";
		print " The logger hexIDs in the cal file and the";
		print " tu file do not match\n";
		print "  -> From ${calfile}:\n";
		print "      Logger hexID is: $sensinfo{hexb}\n";
		print "  -> Expected based on tu file: $tuf\n";
		print "      Logger hexID is: \$$hexb\n\n";
		die;
	    }
	    next;
	}
	if (/^FORMAT/) { # Read calibration format, add to HASH %sensinfo
	    $sensinfo{format} = (split/\s+/, $_)[1]; 
	    if ($sensinfo{format} !~ m/^Yankee|^StdLamp|^Langley/) {
		print "\n                  *** ERROR! ***\n";
		print " There is an error in $calfile\n";
		print " Check line: \"$_\"\n";
		print " It should be set to: Yankee, StdLamp, or Langely";
		print "\n depending on the type of calibration to be used.\n\n";
		die;
	    }
	    if ($sensinfo{format} eq "StdLamp") {$format_flag = "Y";}
	    next;
	}

# Read Lamp serial number if FORMAT_CAL=StdLamp, add to HASH %sensinfo
	if ((/^LAMP_SN/) && ($format_flag eq "Y")) {
	    $sensinfo{lamp} = (split/\s+/, $_)[1]; 
	    if ($sensinfo{lamp} !~ /^\d\d\d\d$/) {
		print "\n                  *** ERROR! ***\n";
		print " There is an error in $calfile\n";
		print " Check line: \"$_\"\n";
		print " It should be set to valid lamp sn, e.g., 1030\n";
		print " Verify the lamp used for this calibration\n\n";
		die;
	    }
	    next;
	}

# Need some sanity code for FORMAT_CAL and LAMP_SN.  If one, then the other
#	if (($sensinfo{format} eq "StdLamp") && ($format_flag eq "N")) {
	    

	if (/^CALI/) {
	    $cal_flag = "Y";
	    next;
	}

	if ($cal_flag eq "Y") {  # Read CALIBRATIONS
	    if (/^OFF/) {        # Exit when OFFSETS encountered
		$cal_flag = "N"; 
		$off_flag = "Y"; 
		next;
	    }
	    my @line = split/\s+/, $_;
	    my $cwl = shift @line;

# 
# Reading in the calibration data for a StdLamp format
#
# THIS CODE IS NOT TRAPPING THE CASE OF A MISSING BB LINE!
#
# AND IS NOT DEALING WITH UVB AND PAR LINES
#
	    if ($sensinfo{format} eq "StdLamp") {
		if ($cwl ne "BB") {
#		print "\$cwl is: $cwl\n";
#		sleep 2;
		    if ((scalar@line < 3) || (scalar@line > 4)) {
			print "\n                     *** ERROR! ***\n";
			print " There is an error in $calfile\n";
			print " with line: \"$cwl   @line\"\n";
			print " When FORMAT_CAL=$sensinfo{format} there";
			print " should be 4 or 5 NARROWBAND fields.\n";
			print " Check the format instructions.\n\n";
			die;
		    } else {
			if (scalar@line == 3) {
			    push @line, 1; # Add scale factor
			}
		    }
		} elsif ($cwl eq "BB") {

#		print "\$cwl is: $cwl\n";
#		sleep 2;
		    my $s = scalar@line;
		    if ((scalar@line < 1) || (scalar@line > 2)) {
			print "\n                     *** ERROR! ***\n";
			print " There is an error in $calfile\n";
			print " with line: \"$cwl   @line\"\n";
			print " When FORMAT_CAL=$sensinfo{format} there";
			print " should be 1 or 2 BB fields.\n";
			print " Check the format instructions.\n\n";
			die;
		    } else {
			if (scalar@line == 1) {
			    push @line, 1; # Add scale factor
			}
		    }
		}
	    }
		

# 
# Reading in the calibration data for a Yankee format
#
	    if ($sensinfo{format} eq "Yankee") {
		if ($cwl ne "BB") {
		    if ((scalar@line < 3) || (scalar@line > 4)) {
			print "\n                     *** ERROR! ***\n";
			print " There is an error in $calfile\n";
			print " with line: \"$cwl   @line\"\n";
			print " When FORMAT_CAL=$sensinfo{format} there";
			print " should be 4 or 5 NARROWBAND fields.\n";
			print " Check the format instructions.\n\n";
			die;
		    } else {
			if (scalar@line == 3) {
			    push @line, 1; # Add scale factor
			}
		    }
		} elsif ($cwl eq "BB") {
		    my $s = scalar@line;
		    if ((scalar@line < 1) || (scalar@line > 2)) {
			print "\n                     *** ERROR! ***\n";
			print " There is an error in $calfile\n";
			print " with line: \"$cwl   @line\"\n";
			print " When FORMAT_CAL=$sensinfo{format} there";
			print " should be 1 or 2 BB fields.\n";
			print " Check the format instructions.\n\n";
			die;
		    } else {
			if (scalar@line == 1) {
			    push @line, 1; # Add scale factor
			}
		    }
		}
	    }
	    

	    my $key;
	    if ($cwl eq "BB") {$key = "ch1";}
	    if ($cwl == 415)  {$key = "ch2";}
	    if ($cwl == 500)  {$key = "ch3";}
	    if ($cwl == 615)  {$key = "ch4";}
	    if ($cwl == 1625) {$key = "ch4";}
	    if ($cwl == 673)  {$key = "ch5";}
	    if ($cwl == 870)  {$key = "ch6";}
	    if ($cwl == 940)  {$key = "ch7";}
#	    print "CAL key is: $key, fields are:  @line\n";
	    $cal{$key} = [ @line ]; # Need @line in square brackets to work
	}

	if ($off_flag eq "Y") {  # Read OFFSETS
	    my (@line) = split/\s+/, $_;
	    my $cwl = shift @line;
	    my $size = scalar @line;
	    while ($size < 5) {
		push @line, 0;
		$size++;
	    }
	    my $key;
	    if ($cwl eq "BB") {$key = "ch1";}
	    if ($cwl == 415)  {$key = "ch2";}
	    if ($cwl == 500)  {$key = "ch3";}
	    if ($cwl == 615)  {$key = "ch4";}
	    if ($cwl == 1625) {$key = "ch4";}
	    if ($cwl == 673)  {$key = "ch5";}
	    if ($cwl == 870)  {$key = "ch6";}
	    if ($cwl == 940)  {$key = "ch7";}
	    $offset{$key} = [ @line ];  # Need @line in square brackets to work
	}
    }

# The offsets in the calibration files are optional.  If no offsets are
# provided they are set to zeros for each channel.  If one or more is
# missing the program dies with an error to check the calibration file.
#
# Filling @offset with zeros.  Order is:
#     Intercept, coef1, coef2, coef3, coef4
#
    my $keynum = keys %offset;
    if ($keynum == 0) {
	foreach my $key (keys %cal) {
	    $offset{$key} = [ (0,0,0,0,0) ]; # Needs the square brackets!!!!
	}
    } elsif (($keynum > 0) && ($keynum < 7)) {
	print "\n                 *** ERROR! ***\n";
	print " We seem to be missing one or more offsets.  There \n";
	print " should be values for each channel, even zeros\n";
	foreach (1 .. 7) {
	    my $key = "ch".$_;
	    if (exists $offset{$key}) {
		print "   $key @{$offset{$key}}\n";
	    } else {
		print "   $key NO VALUES\n";
	    }
	}
	print " Check $calfile for erros/typos\n\n";
	die;
    }
    close (IF);
    return (\%cal, \%offset,\%sensinfo);
}
1;




