####################################################################
# polyeq produces temperature dependent offsets based on the 
# Head_Temp.  It is capable of using a polynomial fit of up to 
# 5 orders.  If the offset is a pure bias, it merely returns the
# single input value.
# 
# Inputs are temperature and reference to array of 5 coefficients.  
# Higher order coefficients are set to zero if the offset is a simple bias.
#
sub polyeq () {
    my $temp     = shift(@_);
    my $ref_coef = shift(@_); # $$rOS{$key}
    my @coef = @$ref_coef;    # De-reference the array

    if (scalar @coef != 5) {
	print "\n              *** ERROR! ***\n";
	print " polyeq requires 5 coefficient inputs.\n";
	print " Check the calibration subroutine and the calibration file.\n";
	print " Array \@coef has too many coefficients (@coef)\n\n";
	die;
    }
    my $var = $coef[0] + ${coef[1]}*$temp + ${coef[2]}*${temp}**2 +
	      ${coef[3]}*${temp}**3 + ${coef[4]}*${temp}**4;
    return $var;
}
1;


#####################################################################
# Subroutine diffusecorr gathers the diffuse corrections.  
#
sub diffusecorr () {
    use strict;
    my $tli  = shift(@_);
    my $type = shift(@_);
    my $date = shift(@_);
    my $lat  = shift(@_);
    my $tuf  = shift(@_); # Working tu file for sanity checks

# Pull IDs from tu file for later sanity checks against dc file
    my ($hexb,$hexh,$sn) = (split /_/,$tuf)[3,4,5];
    $sn = (split /\./,$sn)[0];

    my $path  = "/home/grad/mfrsr/Calinfo/DiffCorr";
    my @listing = `ls ${path}/${tli}_${type}\*.dc`;
    chomp @listing;
    @listing = reverse sort @listing;

    my $dcfile;
  OUTER:
    foreach my $file (@listing) {
	chomp $file;
	
        my ($dcdate) = (split '_',$file)[2]; 

        if ($dcdate <= $date) {
            $dcfile = $file;
            last OUTER;
        }
    }
    if (! -f $dcfile) {
        print "\n                 *** ERROR! ***\n";
        print " There is no DiffCorr (.dc) file for use with date $date\n";
        print " Check ${path}/ for a .dc file \n\n";
        die;
    }
    
    my $hem;
    if ($lat >= 0) {
	$hem = "NORTHERN";
    } else {
	$hem = "SOUTHERN";
    }

    my $hf = "N";   # Hemisphere Flag initialized to No
    my %dc;

# Extract head and board ID info from .dc file for sanity check against .tu file
    my ($hb,$hh,$s) = (split /_/,$dcfile)[3,4,5];
    $s = (split /\./,$s)[0]; # Remove .dc extension

    if ($sn != $s) {  # Compare SNs
	print "\n     ***ERR: May need to create a .dc file!***\n";
	print " The SNs in the dc file and the";
	print " tu file do not match\n";
	print "  -> From ${dcfile}:\n";
	print "      SN is: $s\n";
	print "  -> Expected based on tu file: $tuf\n";
	print "      SN is: $sn\n\n";
	die;
    }
	
    if ($hexh ne $hh) {  # Compare hex Head IDs
	print "\n     ***ERR: May need to create a .dc file!***\n";
	print " The hex Head IDs in the dc file and the";
	print " tu file do not match\n";
	print "  -> From ${dcfile}:\n";
	print "      hexh is: $hh\n";
	print "  -> Expected based on tu file: $tuf\n";
	print "      hexh is: $hexh\n\n";
	die;
    }
	
    if ($hexb ne $hb) {  # Compare hex Logger IDs
	print "\n     ***ERR: May need to create a .dc file!***\n";
	print " The hex Logger IDs in the dc file and the";
	print " tu file do not match\n";
	print "  -> From ${dcfile}:\n";
	print "      hexb is: $hb\n";
	print "  -> Expected based on tu file: $tuf\n";
	print "      hexb is: $hexb\n\n";
	die;
    }
	
    open (IF, $dcfile) or die "Can't open $dcfile: $!\n";
    while (<IF>) {
	chomp;
	if (/^$hem/) {
	    $hf = "Y";
	    next;
	}
	
	if ($hf eq "Y") {
	    if (/^END/) {
		last;
	    }
	    my ($ch,$val) = (split /\s+/, $_)[1,3];
	    my $key = "ch".$ch;
	    $dc{$key} = $val
	}
    }
    return \%dc; # Return hash reference
}
1;




#####################################################################
# Subroutine loggergains gathers logger gain information
#
sub loggergains () {
    my $hexb = shift(@_);

    my $path = "/home/grad/mfrsr/Calinfo/LoggerGains";
    my $file = "${path}/${hexb}";
    if (! -f $file) {
	print "\n              *** ERROR! ***\n";
	print " There is no logger gain file for $hexb\n";
	print " Check $path\n\n";
	die;
    }

    open(LG, $file) or die "Can't open $file: $!\n";

    my %gain;
    while (<LG>) {
	chomp;
	next if /^\s*$/;     # Skip blank lines                             
	next if /^\s*\#/;    # Skip comment lines                           
	s/\#.*$//;           # Strip tag comment                            

	my @line = split, split/\s+/, $_;
	if (scalar @line == 2) {
	    push @line, 0;   # Add zero offset if not given
	}
	my $cwl = shift @line;
	my $key;
	if ($cwl eq "BB") {$key = "ch1";}
	if ($cwl == 415)  {$key = "ch2";}
	if ($cwl == 500)  {$key = "ch3";}
	if ($cwl == 615)  {$key = "ch4";}
	if ($cwl == 1625) {$key = "ch4";}
	if ($cwl == 673)  {$key = "ch5";}
	if ($cwl == 870)  {$key = "ch6";}
	if ($cwl == 940)  {$key = "ch7";}
	if ($cwl eq "TP") {$key = "tp";}
	$gain{$key} = [ @line ];
    }
    close (LG);

#    for my $k1 (keys %gain) {
#	print "$k1\n";
#    }
#    sleep 10;
    return \%gain;
}
1;











